export const LANDMARKS: FeatureCollection<Point> = {
  type: 'FeatureCollection',
  features: PLACES.map(([name, lat, lng, icon, minZoom, maxZoom = 24], i) => ({
    type: 'Feature',
    id: i,
    geometry: { type: 'Point', coordinates: [lng, lat] },
    properties: { name: name.replace(/<br>/g, '\n'), icon, minZoom, maxZoom },
  })),
};

/** The landmarks' names on one line, so the map's own place names can leave them to the landmark doodles. */
export const LANDMARK_NAMES = PLACES.map(([name]) => name.replace(/<br>/g, ' ')).filter(Boolean);
